package com.pridesys.ticketing.repository; import com.pridesys.ticketing.entity.*; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional;
@Repository public class ResetTokenRecordRepository { private final ResetTokenRepository repo; public ResetTokenRecordRepository(ResetTokenRepository r){repo=r;} @Transactional public void invalidateOutstanding(long u,Instant n){repo.invalidateOutstanding(u,n);} @Transactional public void save(long u,String h,Instant e){repo.save(new ResetTokenEntity(u,h,e));} public Optional<TokenRecord> findUsable(String h,Instant n){return repo.findByTokenHash(h).filter(t->t.getUsedAt()==null&&t.getExpiresAt().isAfter(n)).map(t->new TokenRecord(t.getId(),t.getUserId(),t.getExpiresAt(),t.getUsedAt()));} @Transactional public void markUsed(long id,Instant n){var t=repo.findById(id).orElseThrow();t.setUsedAt(n);repo.save(t);} public record TokenRecord(long id,long userId,Instant expiresAt,Instant usedAt){} }
